91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        List<String> missingFields = new ArrayList<>();
120	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
121	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
122	        requireNonBlank(missingFields, "address", ownerFieldsDto.getAddress());
123	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
124	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
125	        if (!missingFields.isEmpty()) {
126	            throw new MissingRequiredFieldsException(missingFields);
127	        }
128	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
129	        requireUniqueTelephone(normalizedTelephone);
130	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
131	        if (!sharesHousehold) {
132	            requireUniqueHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
133	        }
134	        ownerFieldsDto.setTelephone(normalizedTelephone);
135	        if (ownerFieldsDto.getEmail() != null) {
136	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
137	        }
138	        HttpHeaders headers = new HttpHeaders();
139	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
140	        if (owner.getRegistrationDate() == null) {
141	            owner.setRegistrationDate(LocalDate.now());
142	        }
143	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
144	        if (sharesHousehold) {
145	            owner.setHouseholdId(joinHousehold(owner.getLastName(), owner.getAddress()));
146	        }
147	        this.clinicService.saveOwner(owner);
148	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
149	        headers.setLocation(UriComponentsBuilder.newInstance()
150	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
151	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
152	    }
