158	        if (currentOwner == null) {
159	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
160	        }
161	        currentOwner.setAddress(ownerFieldsDto.getAddress());
162	        currentOwner.setCity(ownerFieldsDto.getCity());
163	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
