394	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
395	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress))
396	            .filter(existing -> !householdId.equals(existing.getHouseholdId()))
